"""Build a class-independent Windows 11 screenshot skills mission."""
from pathlib import Path
import html
import json

ROOT = Path(__file__).resolve().parent.parent
TITLE = 'Екранна снимка (Screenshot) в Windows 11 — заснемане и записване'
CSS = '''body{font:19px/1.65 Arial,sans-serif;color:#20354c;background:white;margin:0;padding:24px;max-width:920px;box-sizing:border-box}p{margin:16px 0}h3{font-size:23px;color:#146681;margin:23px 0 10px}strong{color:#155e75}li{margin:10px 0}kbd{display:inline-block;font:700 18px/1.3 Arial,sans-serif;background:white;border:1px solid #b8cddd;border-bottom:3px solid #8ba9bd;border-radius:7px;padding:7px 11px;margin:3px;color:#123c58}figure{margin:20px 0;padding:18px;background:#f1f7fb;border:1px solid #d9e7f1;border-radius:15px;text-align:center}img{display:block;max-width:100%;height:auto;margin:auto}figcaption{font-size:14px;color:#52687d;line-height:1.45;margin-top:10px}.keys{text-align:center;background:#edf5fd;border-radius:14px;padding:20px;margin:18px 0}.key{background:#e8f6ed;border-left:5px solid #399c72;padding:15px 19px;border-radius:8px;margin:18px 0}.example{background:#fff5df;border-left:5px solid #e4aa3b;padding:15px 19px;border-radius:8px;margin:18px 0}.path{background:#edf2f8;padding:13px 16px;border-radius:9px;overflow-wrap:anywhere}.flow{display:flex;flex-wrap:wrap;gap:9px;align-items:center;justify-content:center;background:#edf5fd;padding:18px;border-radius:12px}.flow span{background:white;border:1px solid #c6dbe8;padding:10px;border-radius:9px}.screen{width:88%;max-width:500px;margin:15px auto;border:9px solid #25455d;border-bottom-width:20px;border-radius:12px;background:#e6f1ff;padding:20px;box-sizing:border-box;text-align:left}.selection{padding:16px;border:3px dashed #2088c8;background:white;border-radius:5px}.label{font-size:14px;color:#52687d}.file{font-size:23px;font-weight:bold;color:#125e7a}.calculator{font-size:32px;text-align:right;color:#143f5a;background:#f6f8fb;padding:10px;border-radius:7px}a{color:#126797;overflow-wrap:anywhere}@media(max-width:550px){body{padding:14px}kbd{font-size:16px;padding:6px 8px}.screen{width:100%;padding:12px}.file{font-size:19px}}'''


def wrap(body):
    return '<!doctype html><html lang="bg"><head><meta charset="utf-8"><style>' + CSS + '</style></head><body>' + body + '</body></html>'


def keys(*names):
    return '<div class="keys">' + ' + '.join('<kbd>' + html.escape(n) + '</kbd>' for n in names) + '</div>'


def flow(*labels):
    return '<div class="flow">' + ' → '.join('<span>' + html.escape(v) + '</span>' for v in labels) + '</div>'


def info(sid, title, body):
    return {'id': sid, 'step_content': {'type': 'information', 'title': title, 'instruction': wrap(body), 'instruction_format': 'html'}, 'step_rules': {}}


steps = [
    info('intro', 'За какво е този урок', '''<p><strong>Екранна снимка</strong> — на английски <strong>Screenshot</strong> — е изображение на това, което виждаш на екрана. Можеш да заснемеш целия екран или само избрана част.</p><div class="screen"><div class="label">Примерна схема на екран</div><div class="selection"><strong>Тази област може да стане отделна картинка.</strong></div></div><p>В Windows 11 ще научиш как да снимаш част от екрана с <strong>Windows + Shift + S</strong> и целия екран с <strong>Windows + Print Screen</strong>, как да поставиш снимката в <strong>Paint</strong> и как да я запишеш на диска като <strong>PNG файл</strong>.</p>''' + flow('Заснеми', 'Постави в Paint', 'Запиши PNG', 'Предай файла') + '''<div class="key">Накрая ще предадеш <strong>една собствена екранна снимка</strong> — на част или на целия екран.</div>'''),
    info('prepare', 'Подготви нещо за снимане', '''<ol><li>Отвори <strong>Старт (Start)</strong>, напиши <strong>Калкулатор</strong> или <strong>Calculator</strong> и избери приложението.</li><li>Натисни последователно цифрите <strong>1, 2, 3, 4, 5</strong>. На дисплея ще се появи <strong>12 345</strong> или <strong>12,345</strong> според настройките.</li><li>Остави прозореца на калкулатора видим.</li></ol><div class="screen"><div class="label">Пример за съдържание, което да заснемеш</div><div class="calculator">12 345</div></div><p>Можеш да заснемеш и друг прозорец с учебно съдържание. Избери областта, която искаш да предадеш.</p>'''),
    info('capture-area', 'Снимай част от екрана с Windows + Shift + S', keys('Windows', 'Shift', 'S') + '''<p><strong>Windows</strong> е клавишът с логото на Windows. Комбинацията <strong>Windows + Shift + S</strong> отваря избора на област за екранна снимка в Windows 11.</p><ol><li>Покажи прозореца, който искаш да снимаш.</li><li>Задръж <strong>Windows</strong> и <strong>Shift</strong>, натисни <strong>S</strong> и отпусни клавишите.</li><li>Екранът ще потъмнее и ще се появи лентата на <strong>„Изрязващ инструмент“ (Snipping Tool)</strong>. Избери режим за <strong>снимка</strong> — иконата на фотоапарат, ако има избор между снимка и видео.</li><li>Избери <strong>правоъгълна област (Rectangle)</strong> — иконата на правоъгълник.</li><li>Постави показалеца в горния ляв ъгъл на желаната област. Задръж левия бутон на мишката, издърпай до долния десен ъгъл и отпусни.</li></ol><figure><img src="https://support.microsoft.com/en-us/windows/media/snipping-tool-opened-png.png" alt="Snipping Tool в Windows 11: избран режим за снимка с икона на фотоапарат"><figcaption>Прозорец на Snipping Tool в Windows 11. Иконата на фотоапарат е за снимка. Изображение: Microsoft.</figcaption></figure><p>Снимката се копира в <strong>клипборда</strong> — временно място в паметта, от което можеш да я поставиш в друга програма.</p><div class="key">Следващото действие е <strong>поставяне в Paint</strong>. За нов опит натисни Windows + Shift + S отново. С <strong>Esc</strong> можеш да отмениш започнат избор на област.</div>'''),
    info('paste-paint', 'Постави снимката в Paint', keys('Ctrl', 'V') + '''<ol><li>Отвори <strong>Старт (Start)</strong>, напиши <strong>Paint</strong> и избери приложението.</li><li>В новото празно изображение натисни <strong>Ctrl + V</strong>.</li><li>Заснетата област ще се появи в Paint.</li></ol>''' + flow('Снимка в клипборда', 'Отвори Paint', 'Ctrl + V') + '''<p><strong>Ctrl + V</strong> означава „Постави“. Не е необходимо да рисуваш изображението — поставяш вече заснетата снимка.</p><p>Ако Paint е отворен с друга рисунка, първо я запази, ако ти е нужна. След това избери <strong>Файл → Нов (File → New)</strong> и постави екранната снимка в празното изображение.</p><div class="example">Ако снимката не се появи, върни се към желания прозорец, заснеми го отново с <strong>Windows + Shift + S</strong> и след това опитай Ctrl + V в Paint.</div><p>Между заснемането и поставянето избягвай да копираш друг текст или картинка с Ctrl + C — така можеш да замениш съдържанието на клипборда.</p>'''),
    info('save-png', 'Запиши снимката на диска като PNG', keys('Ctrl', 'S') + '''<p>Вече виждаш снимката в Paint. Сега я запиши като файл, който можеш да намериш и предадеш.</p><ol><li>Натисни <strong>Ctrl + S</strong>. При първото записване ще се отвори прозорец за избор на име и място.</li><li>В прозореца за записване избери <strong>Документи (Documents)</strong>.</li><li>Сега създай папката за снимката: натисни <strong>Нова папка (New folder)</strong>, напиши <strong>Екранни снимки</strong> и натисни <strong>Enter</strong>. Ако папката вече съществува, използвай нея.</li><li>Отвори папката <strong>Екранни снимки</strong> с двойно щракване, ако още не си в нея.</li><li>В полето <strong>Име на файл (File name)</strong> напиши <strong>moqt-screenshot.png</strong>.</li><li>В полето <strong>Тип на файла (Save as type)</strong> избери <strong>PNG</strong>.</li><li>Натисни <strong>Запиши (Save)</strong>.</li></ol><div class="path">Документи → Екранни снимки → <strong>moqt-screenshot.png</strong></div><div class="key"><strong>PNG</strong> е формат за изображения, подходящ за екранни снимки. Файлът вече е записан на диска и може да бъде отворен отново.</div><p>Ако записваш още един опит, използвай друго име, например <strong>moqt-screenshot-2.png</strong>, за да запазиш и предишния.</p><p>Някои версии на Snipping Tool запазват снимки автоматично. За това упражнение използвай файла, който сам записа в избраната папка — така знаеш неговото име и местоположение.</p>'''),
    info('capture-full', 'Друг начин: снимай целия екран', keys('Windows', 'Print Screen') + '''<p>Когато искаш да запазиш всичко видимо на екрана, Windows 11 предлага бърз начин за заснемане направо във файл.</p><ol><li>Подреди прозорците така, както искаш да се виждат на снимката.</li><li>Задръж <strong>Windows</strong>, натисни <strong>Print Screen</strong> и отпусни клавишите. Надписът може да бъде <strong>PrtSc</strong> или <strong>PrtScn</strong>.</li><li>Отвори Файловия мениджър с <strong>Windows + E</strong>.</li><li>Избери <strong>Картини (Pictures)</strong>, след това папката <strong>Екранни снимки (Screenshots)</strong>. Намери най-новата снимка по датата и часа.</li></ol><div class="path">Автоматичният запис обикновено е в: <strong>Картини → Екранни снимки</strong></div><p>На някои клавиатури е необходимо и задържане на <strong>Fn</strong>: <strong>Windows + Fn + PrtSc</strong>. При включено архивиране към OneDrive папката „Картини“ може да е в OneDrive.</p><div class="example">Ако този клавиш липсва или комбинацията не сработва, използвай <strong>Windows + Shift + S</strong> и избери <strong>Цял екран (Full screen)</strong> от режимите. След това постави в Paint и запиши по вече описаните стъпки.</div><p>За последната стъпка е достатъчна <strong>една снимка</strong> — на част или на целия екран. Избери кой от двата начина да използваш.</p>'''),
    info('print-screen-setting', 'Още един вариант: клавишът Prt Scr', keys('Prt Scr') + '''<p>Клавишът <strong>Prt Scr</strong> може да е означен и като <strong>Print Screen</strong>, <strong>PrtSc</strong> или <strong>PrtScn</strong>. Натиснат самостоятелно, той работи според настройката в Windows 11.</p><div class="key"><strong>При включена настройка</strong> за отваряне на заснемането Prt Scr отваря избора на област, както Windows + Shift + S. <strong>При изключена настройка</strong> копира целия екран в клипборда; след това можеш да го поставиш в Paint с Ctrl + V.</div><p>Настройката се намира в <strong>Настройки → Достъпност → Клавиатура (Settings → Accessibility → Keyboard)</strong> — използване на Print Screen за отваряне на заснемането на екрана.</p><p>За упражнението използвай вече обяснените комбинации: <strong>Windows + Shift + S</strong> за избор на област или <strong>Windows + Print Screen</strong> за директно записване на целия екран. Действието им не се променя от тази настройка на самостоятелния Prt Scr.</p>'''),
    info('open-file', 'Намери и отвори записаната снимка', '''<div class="path"><strong>Документи → Екранни снимки → moqt-screenshot.png</strong><br>или при автоматично заснемане:<br><strong>Картини → Екранни снимки → най-новата PNG снимка</strong></div><ol><li>Отвори <strong>Файловия мениджър</strong> с Windows + E.</li><li>Отиди в папката, в която записа снимката.</li><li>Отвори файла с двойно щракване. Той ще се покаже в приложение за изображения.</li><li>Виж дали се чете съдържанието, което искаше да заснемеш — например дисплеят на калкулатора.</li></ol><p>Ако избраната област е неподходяща или текстът е отрязан, направи нова снимка и я запиши с различно име.</p><div class="key">Запомни <strong>името и папката</strong> на изображението, което ще предадеш. В следващата стъпка ще избереш този файл от диска.</div><p>Разширението <strong>.png</strong> може да е скрито в списъка с файлове. В Windows 11 можеш да го покажеш от <strong>Изглед → Показване → Разширения на имената на файловете (View → Show → File name extensions)</strong>.</p>'''),
    {'id': 'submit-image', 'step_content': {'type': 'file', 'title': 'Предай своята екранна снимка', 'instruction': wrap('''<p>Предай <strong>един файл с екранна снимка, която сам направи в Windows 11</strong>. Тя може да показва избрана част или целия екран.</p><div class="key"><strong>Готовият резултат:</strong> изображение, например <strong>moqt-screenshot.png</strong>, на което се вижда заснетото съдържание.</div><ol><li>Натисни бутона <strong>„Избери файл…“</strong> под указанията.</li><li>Отвори папката на снимката. За записаното от Paint изображение това е <strong>Документи → Екранни снимки</strong>; за автоматично записаната снимка — <strong>Картини → Екранни снимки</strong>.</li><li>Избери изображението и натисни <strong>Отвори (Open)</strong>.</li><li>Увери се, че под указанията се показва името на избрания файл.</li><li>Натисни <strong>„Завърши мисията“</strong>, за да приключиш предаването.</li></ol><p>Предай файл във формат <strong>PNG</strong> или <strong>JPG/JPEG</strong>, с размер до <strong>20 MB</strong>.</p>'''), 'instruction_format': 'html'}, 'step_rules': {'send_progress': True}},
]

mission = {'mission_version': 4, 'mission_id': 'basic-skills-windows11-screenshot-20261123-01', 'mission_content': {'title': TITLE, 'category': 'Базови умения', 'description': 'Практически указания за заснемане на част или на целия екран в Windows 11, поставяне в Paint, записване като PNG и предаване на изображението.', 'content_format': 'html', 'steps': steps}, 'mission_rules': {'allow_back_navigation': True, 'show_progress_panel': True}}

if __name__ == '__main__':
    (ROOT / 'windows11-screenshot.mission.json').write_text(json.dumps(mission, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    print('Built', len(steps), 'steps: 8 information + final file submission')
